local ActivityOpenLatticeMainDialog = Class("ActivityOpenLatticeMainDialog")

function ActivityOpenLatticeMainDialog:__init()
    self:Init()
end

function ActivityOpenLatticeMainDialog:Awake()
    self:AddUIClick()
    self.fontStyleButtonEnv = self.BtnNextFloor:GetComponent("FontStyleButton")
end

function ActivityOpenLatticeMainDialog:Init()
    self.activityData = nil
    self.serverData = nil  --服务器数据
    self.AniPlay = false

    self.EventMap = {}
    ---@type ActivityOpenLatticeTaskDialog
    local taskDialog = import("Game.Activity.OpenGrid.ActivityOpenLatticeTaskDialog")
    self.EventMap[taskDialog.CloseEvent] = Events.AddListener(taskDialog.CloseEvent, function(hasUnclaimed)
        self:RefreshShow()
        self:RefreshTaskRedPoint(hasUnclaimed)
    end)
end

function ActivityOpenLatticeMainDialog:__delete()
    for eventName, eventHandler in pairs(self.EventMap) do
        Events.RemoveListener(eventName, eventHandler)
    end
    self.controller = nil
    self.activityData = nil
    self.serverData = nil
    self.AniPlay = false
end

function ActivityOpenLatticeMainDialog:Refresh(data)
    if not data then return end
    self.activityData = data
    self:RefreshStaticUI()
    self:RequestData()
end

function ActivityOpenLatticeMainDialog:RequestData()
    GameUtils.Request(
            Interfaces.ActivityOpenGridHome,
            {activityUuid = self.activityData.id},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    print("---->>"..table.dump(response.data, nil, 3))
                    self.serverData = response.data
                    self.serverData.floor = checkNumber(self.serverData.floor)
                    ---@type BigRewardCellData[]
                    self.bigRewards = {} --左下角大奖列表
                    self.bigRewardsGetCount = 0 --已经领取的要显示的大奖数量
                    
                    local severRewardsShow = checkTable(self.serverData.gridsRewardsShow)
                    for i, v in pairs(severRewardsShow) do
                        ---@type BigRewardCellData
                        local bigReward = {}
                        bigReward.floor = tonumber(i)
                        bigReward.status = v.status
                        bigReward.reward = v.rewards[1]
                        bigReward.isLast = false
                        if v.status == 1 then
                            self.bigRewardsGetCount = self.bigRewardsGetCount + 1
                        end
                        table.insert(self.bigRewards, bigReward)
                    end
                    table.sort(self.bigRewards, function(a, b)
                        return a.floor < b.floor
                    end)
                    if next(self.bigRewards) ~= nil then
                    self.bigRewards[#self.bigRewards].isLast = true
                    end
                    self:RefreshUI()
                end
            end
    )
end

