---刷新左下角大奖列表
function ActivityOpenLatticeMainDialog:RefreshBigRewardLoopView()
    if not self.RewardLoopView.IsListViewInit then
        self.RewardLoopView:InitListView(table.count(self.bigRewards), Bind(self, self.OnGetItemByIndex))    
    end
    self.RewardLoopView:MovePanelToItemIndex(self.bigRewardsGetCount - 1)
end

---@private
function ActivityOpenLatticeMainDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    ---@type ActivityOpenGridBigRewardListCell
    local bigCell = CfUtils.GetLuaScr(cell, BigRewardListCellPath)
    local rewardData = self.bigRewards[index + 1]
    if index < self.bigRewardsGetCount -1 then
        rewardData.fill = 1
    else
        rewardData.fill = 0
    end
    bigCell:RefreshData(rewardData)
    return cell
end
---刷新当前层数和大奖  打开刷新和进入下一层的时候 进行刷新
function ActivityOpenLatticeMainDialog:RefreshCurFloorAndBigRewardShow()
    local curFloor = self:GetCurFloor()
    CfUtils.FillText(self.CurFloor, curFloor or 1)

    local bigReward = self:GetBigReward()
    if not bigReward then return end
    ---@type OpenGridRewardVo
    local openGridRewardVo = CfUtils.GetCfVo(AutoIds.IdSetting6129, "OpenGridRewardVo", bigReward)
    if isTable(openGridRewardVo) then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(openGridRewardVo.reward)
        if isTable(vo) then
            self.ImgGoodsIcon:LoadSprite(vo.photoPath)
            CfUtils.FillText(self.TxtBigRewardNum, openGridRewardVo.rewardNum)
        end
    end
end

function ActivityOpenLatticeMainDialog:RefreshGrid()
    if not self.LatticeList.IsListViewInit then
        self.LatticeList:InitGridView(gridCount, Bind(self, self.OnRefreshIndex))
    else
        self:RefreshGridUI()
    end
end

function ActivityOpenLatticeMainDialog:RefreshGridUI()
    for i = 1 , gridCount do
        local newItem =  self.LatticeList:GetShownItemByItemIndex(i-1)
        if not isNull(newItem) then
            ---@type ActivityOpenLatticeMainGridCell
            local gridCell = CfUtils.GetLuaScr(newItem, GridCellPath)
            local id = isNull(self.serverData) and 0 or  self.serverData.grids[i]
            local data = {gridId = id,isBigReward = self:IsBigReward(id)}
            gridCell:SetButtonAction(function() self:OnGridCellClick(i) end)
            gridCell:RefreshGridUI(data)
        end
    end
end

function ActivityOpenLatticeMainDialog:SetTimeShow()
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TextTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
end

function ActivityOpenLatticeMainDialog:OnRefreshIndex(listView, index, row, col)
    if index < 0 then
        return nil
    end
    --if IsNull(self.serverData) then return end
    local cell = listView:NewListViewItem(ItemCell)
    local gridCell = CfUtils.GetLuaScr(cell, GridCellPath)
    local id = isNull(self.serverData) and 0 or self.serverData.grids[index + 1]
    local data = {gridId = id,isBigReward = self:IsBigReward(id)}
    gridCell:SetButtonAction(function() self:OnGridCellClick(index + 1)  end)
    gridCell:RefreshGridUI(data)
    return cell
end

---设置进入下一层按钮状态
function ActivityOpenLatticeMainDialog:SetBtnNextFloorState()
    local curFloor = self:GetCurFloor()
    if curFloor >= self.serverData.maxFloor then
        CfUtils.SetActive(self.BtnNextFloor.gameObject, false)
        return
    end
    local bigReward = self:GetBigReward()
    if not bigReward then return end
    local isBigRewardGet = self:IsBigRewardGet(bigReward)
    if isBigRewardGet then
        self.fontStyleButtonEnv:ResetFontStyle("B6")
    else
        self.fontStyleButtonEnv:ResetFontStyle("B18")
    end
end

--是否获得了大奖
function ActivityOpenLatticeMainDialog:IsBigRewardGet(id)
    if not isNull(id) and not isNull(self.serverData) then
        for i, v in pairs(self.serverData.grids) do
            if v == id then
                return true
            end
        end
    end
    return false
end

function ActivityOpenLatticeMainDialog:IsBigReward(id)
    local bigReward = self:GetBigReward()
    if not bigReward then return false end
    return bigReward == id
end

---获取大奖的序号
function ActivityOpenLatticeMainDialog:GetBigReward()
    local bigReward = nil
    if not isNull(self.serverData) then
        bigReward = self.serverData.floorFinalGridId
    end
    return bigReward
end

function ActivityOpenLatticeMainDialog:GetCurFloor()
    if not self.serverData then return 1 end
    return self.serverData.floor
end

function ActivityOpenLatticeMainDialog:AddUIClick()
    SetButtonAction(self.BtnTask.gameObject,Bind(self,self.OnBtnTaskClick))
    SetButtonAction(self.BtnNextFloor.gameObject,Bind(self,self.OnBtnNextFloorClick))
    SetButtonAction(self.BtnRule.gameObject,Bind(self,self.OnBtnRuleClick))
    SetButtonAction(self.BtnRewardCheck.gameObject,Bind(self,self.OnBtnRewardCheckClick))
    SetButtonAction(self.BtnSelect.gameObject,Bind(self,self.OnBtnSelectClick))
end

---道具是否足够
function ActivityOpenLatticeMainDialog:IsItemEnough()
