---进入下一层
function ActivityOpenLatticeMainDialog:OnBtnNextFloorClick()
    if self.AniPlay then return end
    local bigReward = self:GetBigReward()
    if not bigReward  then return end
    local isBigRewardGet = self:IsBigRewardGet(bigReward)
    if isBigRewardGet then
        self:EnterNextFloor()
    else
        GameUtils.Toast(localize("翻出本层大奖可进入下一层"))
    end
end

function ActivityOpenLatticeMainDialog:EnterNextFloor()
    GameUtils.Request(
            Interfaces.ActivityOpenGridNextFloor,
            {activityUuid = self.activityData.id},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    print("---->>"..table.dump(response.data, nil, 3))
                    local jsonData = response.data
                    cs_coroutine.start(function()
                        self.AniPlay = true
                        for i, v in pairs(self.serverData.grids) do
                            if v > 0 then
                                local newItem =  self.LatticeList:GetShownItemByItemIndex(i-1)
                                if not isNull(newItem) then
                                    local gridCell = CfUtils.GetLuaScr(newItem, GridCellPath)
                                    gridCell:PlayCloseAni()
                                end
                            end
                        end
                        self.serverData.grids = jsonData.grids
                        self.serverData.floor = jsonData.floor
                        self.serverData.floorFinalGridId = jsonData.floorFinalGridId
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
                        self.AniPlay = false
                        self:RefreshGridUI()
                        self:RefreshCurFloorAndBigRewardShow()
                        self:SetBtnNextFloorState()
                        self:RefreshBigRewardLoopView()
                    end)
                end
            end
    )
end

