function ActivityOpenLatticeMainDialog:OnGridCellClick(_index)
    if self.AniPlay then return end
    
    local function RequestOpenGrid()
        GameUtils.Request(
                Interfaces.ActivityOpenGridFlipGrid,
                {activityUuid = self.activityData.id,index = _index },
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        print("---->>"..table.dump(response.data, nil, 3))
                        local jsonData = response.data
                        self.serverData.grids[_index] = jsonData.gridId
                        cs_coroutine.start(function()
                            local newItem =  self.LatticeList:GetShownItemByItemIndex(_index - 1)
                            if not isNull(newItem) then
                                local gridCell = CfUtils.GetLuaScr(newItem, GridCellPath)
                                local data = {gridId = jsonData.gridId,isBigReward = self:IsBigReward(jsonData.gridId)}
                                gridCell:RefreshGridUI(data)
                                gridCell:PlayOpenAni()
                                self.AniPlay = true
                            end
                            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                            local data = self:GetStaticData()
                            GoodsUtils.ConsumeGoods({ {goodsId = data.consume, num = data.cost } } , true)
                            self:RefreshShow()
                            self:SetBtnNextFloorState()
                            self.AniPlay = false
                            local rewardData = checkTable(jsonData.rewards)
                            if not isNull(rewardData) and #rewardData > 0 then
                                GoodsUtils.DrawRewards(rewardData, true)
                                local isBigReward = self:IsBigReward(jsonData.gridId)
                                local curState = PlayerPrefsUtility.GetEncryptedBool(Constants.UICacheDataKeys.UI_Activity_OpenGrid_Select_Pop, false)
                                if not curState then
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData, cb = function()
                                        if isBigReward then
                                            GameUtils.Toast(localize("恭喜获得本层大奖，可点击进入一层！"))
                                        end
                                    end } })
                                else
                                    if isBigReward then
                                        GameUtils.Toast(localize("恭喜获得本层大奖，可点击进入一层！"))
                                    end
                                end

                                if isBigReward then
                                    local nextShowBigReward = self.bigRewards[self.bigRewardsGetCount + 1]
                                    if nextShowBigReward then
                                        if nextShowBigReward.floor == self:GetCurFloor() then
                                            nextShowBigReward.status = 1
                                            local cur = self.RewardLoopView:GetShownItemByItemIndex(self.bigRewardsGetCount - 1)
                                            local animTime = 0.5
                                            if not isNull(cur) then
                                                ---@type ActivityOpenGridBigRewardListCell
                                                local bigCell = CfUtils.GetLuaScr(cur, BigRewardListCellPath)
                                                bigCell:PlayFill(animTime)
                                            end
                                            local next = self.RewardLoopView:GetShownItemByItemIndex(self.bigRewardsGetCount)
                                            if not isNull(next) then
                                                cs_coroutine.start(function() 
                                                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animTime))
                                                    ---@type ActivityOpenGridBigRewardListCell
                                                    local bigCell = CfUtils.GetLuaScr(next, BigRewardListCellPath)
                                                    bigCell:RefreshData(nextShowBigReward)
                                                end)
                                            end
                                            self.bigRewardsGetCount = self.bigRewardsGetCount + 1
                                        end
                                    end
                                end
                            end
                        end)
                    end
                end
        )
    end
    
    if  self:IsItemEnough()  then
        RequestOpenGrid()
    else
        local data = self:GetStaticData()
        local goodsId = data.consume
        local goodsNum = data.cost
        
        local consumeId ,consumeRate = ActivityMgr:GetGoodsPrice(goodsId)
        local consumeCount = goodsNum * consumeRate

        local youHave = GoodsUtils.GetThingNo(consumeId)
        printInfo("youHave======>>"..tostring(youHave))
        if youHave > consumeCount then
            UIModule.OpenDialog({
                id = Constants.UITypeIds.GachaponConfirm,
                parameters = {
                    type = GachaponConstants.ConfirmType.IconToIcon,
                    poolType = GachaponConstants.PoolType.Regular,
                    onConfirm = function()
                        ActivityMgr:RequestBuyActivityGoods(self.activityData.id, self.activityData.type, goodsId, goodsNum, function()
                            GoodsUtils.ConsumeGoods({ {goodsId = consumeId, num = consumeCount } } , true)
                            RequestOpenGrid()
                        end)
                    end,
                    leftParam = {
                        goodsId = consumeId,
                        num = consumeCount
                    },
                    rightParam = {
                        goodsId = goodsId,
                        num = goodsNum
                    }
                }
            })
        else
            local buyCallBack = function()
                ActivityMgr:RequestBuyActivityGoods(self.activityData.id, self.activityData.type, goodsId, goodsNum, function()
                    GoodsUtils.ConsumeGoods({ {goodsId = consumeId, num = consumeCount } } , true)
                    RequestOpenGrid()
                end)
            end
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            if ServerDifferenceMgr:IsSecondaryCurrencyEnable() then
                ---@type CommonCurrencyExchangePopup.InputData
                local data = {
                    leftId = Constants.Currency.FreeDiamondId,
                    leftNum = consumeCount,
                    rightId = goodsId,
                    rightNum = goodsNum,
                    onConfirmClick = buyCallBack,
                }
                ServerDifferenceMgr:OpenCurrencyExchangePopup(data)
            else
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.FreeDiamondId)
                GameUtils.SecondConfirm
                (
                        localize("_name_不足, 是否前往充值？", {_name_ = goodsVo.name}),
                        function()
                            ---@type OverseaStoreUtils
                            local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
                            ---@type OverseaStoreConstants
                            local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
                            OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp)
                        end
                )
            end
        end
    end
end

