function ActivityOpenLatticeMainDialog:RefreshTaskRedPoint(status)
    print("FreshTaskRedPoint======>>"..tostring(status))
    if isNull(self.serverData) then
        return
    end
    local redPointGo = GameUtils.GetRedPointGo(self.BtnTask)
    local isActive
    if isNull(status) then
        isActive = self.serverData.taskRedDotHint >=0
    else
        isActive = status
        self.serverData.taskRedDotHint = status and 0 or -1
    end
    KTool.SetActive(redPointGo, isActive)
end

function ActivityOpenLatticeMainDialog:RefreshSupplyShopRedDot(status)
    if isNull(self.serverData) then
        return
    end
end

function ActivityOpenLatticeMainDialog:RefreshActivityRedPoint()
    if self:IsAllClear() then
        Events.Broadcast(Constants.EventNames.ActivityRedPointChange, self.activityData.id, -1)
        return
    end
    
    local isActive
    local isItemEnough = self:IsItemEnough()
    local isTaskActive = self.serverData.taskRedDotHint >= 0 and true or false
    isActive = isItemEnough or isTaskActive
    Events.Broadcast(Constants.EventNames.ActivityRedPointChange, self.activityData.id, isActive and 0 or -1)
end

function ActivityOpenLatticeMainDialog:IsAllClear()
    local floor = self:GetCurFloor()
    if floor < self.serverData.maxFloor then
        return false
    end
    for i, v in pairs(self.serverData.grids) do
        if v <= 0 then
            return false
        end
    end
    return true
end
return ActivityOpenLatticeMainDialog